solutionSql:
CREATE TABLE departments (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL
);

CREATE TABLE employees (
  id INTEGER PRIMARY KEY,
  department_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  hired_at TEXT NOT NULL,
  FOREIGN KEY (department_id) REFERENCES departments(id)
);
